/**
 * Reads the allowlist the Cursor MCP gateway reports on `tools/list`, under
 * `_meta.mcpAllowlist`. The report is display only. A listing without the key
 * or with a malformed one reads as no report, and never fails the listing.
 */
import { isRecord } from "./is-record.js";
const MAX_TEXT_LENGTH = 200;
const MAX_SERVER_NAME_LENGTH = 200;
const MAX_SERVERS = 200;
const MAX_SERVERS_SHOWN = 20;
/** One line of printable text within `maxLength`, or undefined. */
function displayText(value, maxLength) {
    if (typeof value !== "string") {
        return undefined;
    }
    const text = value.trim();
    if (text === "" || text.length > maxLength || /\p{Cc}/u.test(text)) {
        return undefined;
    }
    return text;
}
/** The allowlist report in a `tools/list` result's `_meta`, or undefined when absent or malformed. */
export function parseMcpAllowlistInUse(meta) {
    if (!isRecord(meta)) {
        return undefined;
    }
    const reported = meta.mcpAllowlist;
    if (!isRecord(reported) || typeof reported.list !== "string") {
        return undefined;
    }
    const name = displayText(reported.name, MAX_TEXT_LENGTH);
    const reason = displayText(reported.reason, MAX_TEXT_LENGTH);
    if (name === undefined || reason === undefined) {
        return undefined;
    }
    const inUse = {
        list: reported.list === "local" || reported.list === "cloud" ? reported.list : "other",
        name,
        reason,
    };
    // `allowedServerNames` holds display names. `allowedServers` can hold
    // connection identifiers, so it is read only when the names are absent.
    const allowedServers = serverNames(reported.allowedServerNames) ?? serverNames(reported.allowedServers);
    if (allowedServers !== undefined) {
        inUse.allowedServers = allowedServers;
    }
    const blockedServers = serverNames(reported.blockedServers);
    if (blockedServers !== undefined) {
        inUse.blockedServers = blockedServers;
    }
    return inUse;
}
/** The printable names in a reported server list, or undefined when it is not a list. */
function serverNames(reported) {
    if (!Array.isArray(reported)) {
        return undefined;
    }
    const names = [];
    for (const server of reported.slice(0, MAX_SERVERS)) {
        const serverName = displayText(server, MAX_SERVER_NAME_LENGTH);
        if (serverName !== undefined) {
            names.push(serverName);
        }
    }
    return names;
}
/** `names` after `label`, the first few by name and the rest as a count. */
function serversSentence(label, names) {
    const shown = names.slice(0, MAX_SERVERS_SHOWN).join(", ");
    const more = names.length - MAX_SERVERS_SHOWN;
    return more > 0 ? ` ${label}: ${shown}, and ${more} more.` : ` ${label}: ${shown}.`;
}
function allowedServersSentence(allowedServers) {
    if (allowedServers === undefined) {
        return "";
    }
    return allowedServers.length === 0
        ? " Allowed servers: none."
        : serversSentence("Allowed servers", allowedServers);
}
/** Nothing when the gateway named no blocked server. */
function blockedServersSentence(blockedServers) {
    return blockedServers === undefined || blockedServers.length === 0
        ? ""
        : serversSentence("Blocked", blockedServers);
}
/**
 * The list, why it applies, the servers it allowed and the ones it blocked, as
 * sentences that follow a caller's own lead-in.
 */
export function describeMcpAllowlistInUse(inUse) {
    return `${inUse.name}, which applies because ${inUse.reason}.${allowedServersSentence(inUse.allowedServers)}${blockedServersSentence(inUse.blockedServers)}`;
}
